def main():
    racine = os.getcwd()
    if not all(os.path.exists(os.path.join(racine, f)) for f in ("cellule.py", "adn.py", "bibliotheque_genomes.py")):
        print("ERREUR : lancez ce script depuis le dossier RiboSound (celui qui contient cellule.py, adn.py et bibliotheque_genomes.py).")
        sys.exit(1)
    maintenant = datetime.datetime.now()
    copie = os.path.join(racine, "sauvegardes", "patch_" + maintenant.strftime("%Y%m%d_%H%M%S"))
    sauvegardes, crees = [], []
    try:
        for chemin, b64 in FICHIERS.items():
            cible = os.path.join(racine, chemin)
            if os.path.exists(cible):
                bak = os.path.join(copie, chemin)
                os.makedirs(os.path.dirname(bak), exist_ok=True)
                shutil.copy2(cible, bak)
                sauvegardes.append((cible, bak))
            else:
                crees.append(cible)
            os.makedirs(os.path.dirname(cible), exist_ok=True)
            with open(cible, "wb") as f:
                f.write(base64.b64decode("".join(b64)))
        for py in ("serveur.py", "api_genomes.py", "api_petri.py", "api_ecoute.py", "api_lectures.py", "rendu_proc.py"):
            py_compile.compile(os.path.join(racine, "interface", py), doraise=True)
        print(f"{len(FICHIERS)} fichiers installés, syntaxe Python : OK")
        print("Copie des anciens fichiers :", copie)
    except Exception as e:
        print("ERREUR :", e, "-> retour arrière")
        for cible, bak in sauvegardes:
            shutil.copy2(bak, cible)
        for cible in crees:
            if os.path.exists(cible):
                os.remove(cible)
        sys.exit(1)
    passation = os.path.join(racine, "PASSATION.md")
    entete = "## Session " + maintenant.strftime("%Y-%m-%d") + " (Claude)"
    try:
        actuel = open(passation, encoding="utf-8").read() if os.path.exists(passation) else ""
        if entete not in actuel:
            with open(passation, "a", encoding="utf-8") as f:
                f.write(SESSION.format(date=maintenant.strftime("%Y-%m-%d")))
            print("PASSATION.md : section de session ajoutée")
    except OSError as e:
        print("PASSATION.md non modifié :", e)
    print("\nRedémarrez le studio :")
    print("  bash interface/arret-studio.sh; RIBOSOUND_PYTHON=$(which python) bash interface/demarrer-studio.sh")
    print("Puis, dans le navigateur : Ctrl+Maj+R. Les onglets « Bibliothèque », « Lectures », « Petri » et « Écoute » apparaissent dans la barre du haut.")


if __name__ == "__main__":
    main()
